components.styles:
.ehs-ui {
  --ehs-primary: var(--md-sys-color-primary);
  --ehs-on-primary: var(--md-sys-color-on-primary);
  --ehs-primary-soft: var(--md-sys-color-primary-container);
  --ehs-on-primary-soft: var(--md-sys-color-on-primary-container);
  --ehs-secondary: var(--md-sys-color-secondary);
  --ehs-on-secondary: var(--md-sys-color-on-secondary);
  --ehs-secondary-soft: var(--md-sys-color-secondary-container);
  --ehs-on-secondary-soft: var(--md-sys-color-on-secondary-container);
  --ehs-tertiary: var(--md-sys-color-tertiary);
  --ehs-on-tertiary: var(--md-sys-color-on-tertiary);
  --ehs-tertiary-soft: var(--md-sys-color-tertiary-container);
  --ehs-on-tertiary-soft: var(--md-sys-color-on-tertiary-container);
  --ehs-accent: var(--md-sys-color-tertiary);
  --ehs-success: var(--ehs-status-success);
  --ehs-on-success: var(--ehs-status-on-success);
  --ehs-success-soft: var(--ehs-status-success-container);
  --ehs-on-success-soft: var(--ehs-status-on-success-container);
  --ehs-warning: var(--ehs-status-warning);
  --ehs-on-warning: var(--ehs-status-on-warning);
  --ehs-warning-soft: var(--ehs-status-warning-container);
  --ehs-on-warning-soft: var(--ehs-status-on-warning-container);
  --ehs-danger: var(--md-sys-color-error);
  --ehs-on-danger: var(--md-sys-color-on-error);
  --ehs-danger-soft: var(--md-sys-color-error-container);
  --ehs-on-danger-soft: var(--md-sys-color-on-error-container);
  --ehs-info: var(--ehs-status-info);
  --ehs-on-info: var(--ehs-status-on-info);
  --ehs-info-soft: var(--md-sys-color-tertiary-container);
  --ehs-on-info-soft: var(--md-sys-color-on-tertiary-container);
  --ehs-surface: var(--md-sys-color-surface);
  --ehs-bg: var(--md-sys-color-background);
  --ehs-text: var(--md-sys-color-on-surface);
  --ehs-muted: var(--md-sys-color-on-surface-variant);
  --ehs-border: var(--md-sys-color-outline-variant);
  --ehs-control-border: var(--md-sys-color-outline);
  --ehs-radius: var(--md-sys-shape-corner-small);
  --ehs-radius-lg: var(--md-sys-shape-corner-medium);
  --ehs-shadow-1: 0 1px 2px rgb(0 0 0 / 18%),0 1px 3px 1px rgb(0 0 0 / 8%);
  --ehs-shadow-2: 0 1px 2px rgb(0 0 0 / 18%),0 2px 6px 2px rgb(0 0 0 / 10%);
  --ehs-shadow-3: 0 1px 3px rgb(0 0 0 / 18%),0 4px 8px 3px rgb(0 0 0 / 10%);
  --ehs-font: var(--md-sys-font-family-base);
  --ehs-control-height: 3.5rem;
  --ehs-button-height: 2.5rem;
  font: 400 1rem/1.5 var(--ehs-font);
  color: var(--ehs-text);
  background: var(--ehs-bg);
  text-align: start;
  accent-color: var(--ehs-primary);
}

.ehs-ui[data-ehs-density="compact"] {
  --ehs-control-height: 2.75rem;
  font-size: .875rem;
}

@media (pointer: coarse) {
  .ehs-ui {
    --ehs-button-height: 3rem;
  }
}

.ehs-ui, .ehs-ui *, .ehs-ui *::before, .ehs-ui *::after {
  box-sizing: border-box;
}

.ehs-ui :where(button,input,select,textarea) {
  font: inherit;
}

.ehs-ui :where(button,a,input,select,textarea,summary,[tabindex]):focus-visible {
  outline: 3px solid var(--ehs-primary);
  outline-offset: 3px;
}

.ehs-ui [hidden] {
  display: none !important;
}

.ehs-ui :where(h1,h2,h3,h4,h5,h6,p) {
  margin-block: 0 1rem;
}

.ehs-ui :where(h1,h2,h3,h4,h5,h6) {
  line-height: 1.25;
}

.ehs-ui :where(a) {
  color: var(--ehs-primary);
  text-underline-offset: .2em;
}

.ehs-ui :where(button) {
  cursor: pointer;
}

.ehs-ui :where(button:disabled,input:disabled,select:disabled,textarea:disabled) {
  cursor: not-allowed;
  opacity: .6;
}

.ehs-container,.ehs-container-fluid {
  width: 100%;
  margin-inline: auto;
  padding-inline: 1rem;
}

.ehs-row {
  --ehs-gx: 1.5rem;
  --ehs-gy: 0rem;
  display: flex;
  flex-wrap: wrap;
  margin-inline: calc(var(--ehs-gx) / -2);
  margin-block-start: calc(-1 * var(--ehs-gy));
}

.ehs-row > * {
  flex: 0 0 auto;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  padding-inline: calc(var(--ehs-gx) / 2);
  margin-block-start: var(--ehs-gy);
}

.ehs-stack {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.ehs-cluster {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .5rem;
}

.ehs-grid {
  display: grid;
  gap: 1rem;
}

.ehs-btn {
  --ehs-btn-bg: var(--ehs-surface);
  --ehs-btn-fg: var(--ehs-text);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  min-height: var(--ehs-control-height);
  padding: .5rem 1rem;
  border: 1px solid var(--ehs-control-border);
  border-radius: var(--ehs-radius);
  background: var(--ehs-btn-bg);
  color: var(--ehs-btn-fg);
  font-weight: 600;
  line-height: 1.35;
  text-decoration: none;
  vertical-align: middle;
  transition: box-shadow .15s, background .15s;
}

.ehs-btn:hover:not(:disabled):not([aria-disabled="true"]) {
  box-shadow: var(--ehs-shadow-1);
  background-image: linear-gradient(rgb(0 0 0 / 7%),rgb(0 0 0 / 7%));
}

.ehs-btn[aria-disabled="true"] {
  opacity: .6;
  cursor: not-allowed;
}

.ehs-btn-sm {
  min-height: 2rem;
  padding: .3rem .65rem;
  font-size: .875rem;
}

.ehs-btn-lg {
  min-height: 3.25rem;
  padding: .75rem 1.4rem;
  font-size: 1.125rem;
}

.ehs-btn-icon {
  width: var(--ehs-control-height);
  padding: .5rem;
  flex-shrink: 0;
}

.ehs-btn-text {
  background: transparent;
  border-color: transparent;
  color: var(--ehs-primary);
}

.ehs-btn-group {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 1px;
}

.ehs-card {
  background: var(--ehs-surface);
  border: 1px solid var(--ehs-border);
  border-radius: var(--ehs-radius-lg);
  box-shadow: var(--ehs-shadow-1);
  min-width: 0;
}

.ehs-card-header,.ehs-card-body,.ehs-card-footer {
  padding: 1.25rem;
}

.ehs-card-header {
  border-block-end: 1px solid var(--ehs-border);
}

.ehs-card-footer {
  border-block-start: 1px solid var(--ehs-border);
}

.ehs-card-title {
  margin-block: 0 .5rem;
  font-size: 1.125rem;
  font-weight: 700;
}

.ehs-card-subtitle {
  color: var(--ehs-muted);
  font-size: .875rem;
}

.ehs-card-img {
  display: block;
  width: 100%;
  height: auto;
  border-start-start-radius: var(--ehs-radius-lg);
  border-start-end-radius: var(--ehs-radius-lg);
}

.ehs-card-flat {
  box-shadow: none;
}

.ehs-label {
  display: block;
  font-weight: 600;
  margin-block-end: .4rem;
}

.ehs-input,.ehs-select,.ehs-textarea {
  display: block;
  width: 100%;
  min-width: 0;
  min-height: var(--ehs-control-height);
  padding: .55rem .75rem;
  border: 1px solid var(--ehs-control-border);
  border-radius: var(--ehs-radius);
  background: var(--ehs-surface);
  color: var(--ehs-text);
}

.ehs-select {
  padding-inline-end: 1.5rem;
}

.ehs-textarea {
  min-height: 6rem;
  resize: vertical;
}

.ehs-input::placeholder,.ehs-textarea::placeholder {
  color: var(--ehs-muted);
  opacity: 1;
}

.ehs-input[readonly] {
  background: var(--ehs-bg);
}

.ehs-help {
  display: block;
  color: var(--ehs-muted);
  font-size: .875rem;
  margin-block-start: .35rem;
}

.ehs-invalid-feedback {
  display: block;
  color: var(--ehs-danger);
  font-size: .875rem;
  margin-block-start: .35rem;
}

.ehs-input[aria-invalid="true"],.ehs-select[aria-invalid="true"],.ehs-textarea[aria-invalid="true"] {
  border: 2px solid var(--ehs-danger);
}

.ehs-input-group {
  display: flex;
  align-items: stretch;
}

.ehs-input-group > .ehs-input {
  flex: 1;
  width: 1%;
  border-radius: 0;
}

.ehs-input-group > :first-child {
  border-start-start-radius: var(--ehs-radius);
  border-end-start-radius: var(--ehs-radius);
}

.ehs-input-group > :last-child {
  border-start-end-radius: var(--ehs-radius);
  border-end-end-radius: var(--ehs-radius);
}

.ehs-input-addon {
  display: flex;
  align-items: center;
  padding-inline: .75rem;
  border: 1px solid var(--ehs-control-border);
  background: var(--ehs-bg);
}

.ehs-check {
  display: flex;
  align-items: center;
  gap: .6rem;
  min-height: 2.75rem;
  cursor: pointer;
}

.ehs-check-input {
  width: 1.125rem;
  height: 1.125rem;
  flex-shrink: 0;
}

.ehs-switch {
  appearance: none;
  width: 2.6rem;
  height: 1.5rem;
  margin: 0;
  padding: 2px;
  border: 1px solid var(--ehs-control-border);
  border-radius: 2rem;
  background: var(--ehs-muted);
  cursor: pointer;
  flex-shrink: 0;
}

.ehs-switch::before {
  content: "";
  display: block;
  width: 1.1rem;
  height: 1.1rem;
  border-radius: 50%;
  background: white;
  transition: transform .15s;
}

.ehs-switch:checked {
  background: var(--ehs-primary);
}

.ehs-switch:checked::before {
  transform: translateX(1.05rem);
}

.ehs-switch:dir(rtl):checked::before {
  transform: translateX(-1.05rem);
}

.ehs-range {
  width: 100%;
  min-height: 2rem;
}

.ehs-fieldset {
  min-width: 0;
  border: 1px solid var(--ehs-border);
  border-radius: var(--ehs-radius);
  padding: 1rem;
}

.ehs-fieldset > legend {
  padding-inline: .5rem;
  font-weight: 600;
}

.ehs-badge,.ehs-chip {
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  border-radius: 2rem;
  padding: .25rem .65rem;
  font-size: .8125rem;
  font-weight: 600;
  background: var(--ehs-primary-soft);
  color: var(--ehs-primary);
}

.ehs-chip {
  font-size: .875rem;
}

.ehs-chip > button {
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  min-width: 1.75rem;
  min-height: 1.75rem;
}

.ehs-alert {
  padding: 1rem;
  border: 1px solid var(--ehs-border);
  border-inline-start: 4px solid var(--ehs-primary);
  border-radius: var(--ehs-radius);
  background: var(--ehs-primary-soft);
  color: var(--ehs-primary);
}

.ehs-divider {
  border: 0;
  border-block-start: 1px solid var(--ehs-border);
  margin-block: 1rem;
}

.ehs-table-responsive {
  overflow-x: auto;
  max-width: 100%;
  border: 1px solid var(--ehs-border);
  border-radius: var(--ehs-radius);
}

.ehs-table {
  width: 100%;
  border-collapse: collapse;
  background: var(--ehs-surface);
  color: var(--ehs-text);
  font-size: .9375rem;
}

.ehs-table :where(th,td) {
  padding: .875rem 1rem;
  text-align: start;
  border-block-end: 1px solid var(--ehs-border);
  vertical-align: middle;
}

.ehs-table :where(thead th) {
  background: var(--ehs-bg);
  color: var(--ehs-muted);
  font-size: .8125rem;
  font-weight: 700;
}

.ehs-table caption {
  padding: .75rem 1rem;
  text-align: start;
  font-weight: 600;
  caption-side: top;
}

.ehs-table-striped tbody tr:nth-child(even) {
  background: var(--ehs-bg);
}

.ehs-table-hover tbody tr:hover {
  background: var(--ehs-primary-soft);
}

.ehs-table-bordered :where(th,td) {
  border: 1px solid var(--ehs-border);
}

.ehs-table-sm :where(th,td) {
  padding: .5rem .75rem;
}

.ehs-table-sticky thead th {
  position: sticky;
  top: 0;
  z-index: 1;
}

.ehs-table-numeric {
  text-align: end !important;
  font-variant-numeric: tabular-nums;
}

.ehs-table-sort {
  color: inherit;
  background: transparent;
  border: 0;
  font-weight: inherit;
  padding: .25rem;
  text-align: inherit;
}

.ehs-accordion {
  border: 1px solid var(--ehs-border);
  border-radius: var(--ehs-radius);
  background: var(--ehs-surface);
}

.ehs-accordion-item + .ehs-accordion-item {
  border-block-start: 1px solid var(--ehs-border);
}

.ehs-accordion-trigger {
  padding: 1rem 1.25rem;
  cursor: pointer;
  font-weight: 600;
}

.ehs-accordion-item[open] > .ehs-accordion-trigger {
  color: var(--ehs-primary);
  background: var(--ehs-primary-soft);
}

.ehs-accordion-body {
  padding: 1rem 1.25rem;
}

.ehs-tabs {
  display: flex;
  gap: .25rem;
  overflow-x: auto;
  border-block-end: 1px solid var(--ehs-border);
}

.ehs-tab {
  flex-shrink: 0;
  border: 0;
  border-block-end: 3px solid transparent;
  background: transparent;
  color: var(--ehs-muted);
  padding: .85rem 1.1rem;
  font-weight: 600;
}

.ehs-tab[aria-selected="true"] {
  color: var(--ehs-primary);
  border-block-end-color: var(--ehs-primary);
  background: var(--ehs-primary-soft);
}

.ehs-tab-panel {
  padding-block: 1rem;
}

.ehs-stepper {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: .75rem;
  padding: 0;
  margin-block: 0 1.5rem;
  counter-reset: ehs-step;
}

.ehs-step {
  flex: 1 1 8rem;
  display: flex;
  align-items: center;
  gap: .65rem;
  color: var(--ehs-muted);
  padding: .75rem;
  border-block-end: 3px solid var(--ehs-border);
}

.ehs-step::before {
  counter-increment: ehs-step;
  content: counter(ehs-step);
  display: grid;
  place-items: center;
  width: 2rem;
  height: 2rem;
  flex-shrink: 0;
  background: var(--ehs-bg);
  border: 1px solid var(--ehs-border);
  border-radius: 50%;
}

.ehs-step[aria-current="step"] {
  color: var(--ehs-primary);
  font-weight: 700;
  border-color: var(--ehs-primary);
}

.ehs-step.ehs-is-complete {
  color: var(--ehs-success);
  border-color: var(--ehs-success);
}

.ehs-step.ehs-is-complete::before {
  content: "✓";
  background: var(--ehs-success-soft);
}

.ehs-stepper-vertical {
  flex-direction: column;
}

.ehs-stepper-vertical > .ehs-step {
  flex-basis: auto;
  border-block-end: 0;
  border-inline-start: 3px solid var(--ehs-border);
}

.ehs-stepper-vertical > .ehs-step[aria-current="step"] {
  border-inline-start-color: var(--ehs-primary);
}

.ehs-stepper-vertical > .ehs-step.ehs-is-complete {
  border-inline-start-color: var(--ehs-success);
}

.ehs-modal,.ehs-drawer {
  color: var(--ehs-text);
  background: var(--ehs-surface);
  border: 1px solid var(--ehs-border);
  border-radius: var(--ehs-radius-lg);
  box-shadow: var(--ehs-shadow-3);
  padding: 0;
  width: min(36rem,calc(100% - 2rem));
  max-height: calc(100dvh - 2rem);
  overflow: auto;
}

.ehs-modal::backdrop,.ehs-drawer::backdrop {
  background: rgb(6 25 40 / 55%);
}

.ehs-modal-header,.ehs-modal-body,.ehs-modal-footer {
  padding: 1.25rem;
}

.ehs-modal-header,.ehs-modal-footer {
  display: flex;
  align-items: center;
  gap: .75rem;
  flex-wrap: wrap;
}

.ehs-modal-header {
  border-block-end: 1px solid var(--ehs-border);
  justify-content: space-between;
}

.ehs-modal-footer {
  border-block-start: 1px solid var(--ehs-border);
  justify-content: flex-end;
}

.ehs-modal-sm {
  width: min(24rem,calc(100% - 2rem));
}

.ehs-modal-lg {
  width: min(56rem,calc(100% - 2rem));
}

.ehs-drawer {
  position: fixed;
  inset-block: 0;
  inset-inline-start: auto;
  inset-inline-end: 0;
  margin: 0;
  width: min(24rem,100%);
  height: 100dvh;
  max-height: 100dvh;
  border-radius: 0;
}

.ehs-dropdown {
  display: inline-block;
  position: relative;
}

.ehs-dropdown > summary {
  list-style: none;
}

.ehs-dropdown > summary::-webkit-details-marker {
  display: none;
}

.ehs-dropdown-menu {
  position: absolute;
  inset-inline-end: 0;
  top: calc(100% + .35rem);
  z-index: 30;
  min-width: 12rem;
  max-width: calc(100vw - 2rem);
  padding: .4rem;
  background: var(--ehs-surface);
  border: 1px solid var(--ehs-border);
  border-radius: var(--ehs-radius);
  box-shadow: var(--ehs-shadow-2);
}

.ehs-dropdown-item {
  display: block;
  width: 100%;
  border: 0;
  border-radius: .25rem;
  padding: .65rem .75rem;
  text-align: start;
  background: transparent;
  color: var(--ehs-text);
  text-decoration: none;
}

.ehs-dropdown-item:hover {
  background: var(--ehs-primary-soft);
  color: var(--ehs-primary);
}

.ehs-navbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
  padding: 1rem 1.25rem;
  background: var(--ehs-surface);
  border-block-end: 1px solid var(--ehs-border);
}

.ehs-navbar-brand {
  color: var(--ehs-primary);
  font-weight: 800;
  font-size: 1.2rem;
  text-decoration: none;
}

.ehs-nav {
  display: flex;
  flex-wrap: wrap;
  gap: .25rem;
  padding: 0;
  list-style: none;
}

.ehs-nav-link {
  display: block;
  padding: .65rem .85rem;
  border-radius: var(--ehs-radius);
  text-decoration: none;
  color: var(--ehs-muted);
}

.ehs-nav-link:hover,.ehs-nav-link[aria-current="page"] {
  color: var(--ehs-primary);
  background: var(--ehs-primary-soft);
}

.ehs-sidebar {
  padding: 1rem;
  background: var(--ehs-surface);
  border-inline-end: 1px solid var(--ehs-border);
}

.ehs-sidebar .ehs-nav {
  flex-direction: column;
}

.ehs-breadcrumb {
  display: flex;
  flex-wrap: wrap;
  gap: .5rem;
  list-style: none;
  padding: 0;
  font-size: .875rem;
  color: var(--ehs-muted);
}

.ehs-breadcrumb > li + li::before {
  content: "/";
  padding-inline-end: .5rem;
  color: var(--ehs-muted);
}

.ehs-pagination {
  display: flex;
  gap: .3rem;
  flex-wrap: wrap;
  padding: 0;
  list-style: none;
}

.ehs-page-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 2.75rem;
  min-height: 2.75rem;
  border: 1px solid var(--ehs-border);
  border-radius: var(--ehs-radius);
  background: var(--ehs-surface);
  color: var(--ehs-primary);
  text-decoration: none;
}

.ehs-page-link[aria-current="page"] {
  background: var(--ehs-primary-soft);
  border-color: var(--ehs-primary);
  font-weight: 700;
}

.ehs-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.ehs-list-item {
  padding: .85rem 1rem;
  border-block-end: 1px solid var(--ehs-border);
}

.ehs-avatar {
  display: inline-grid;
  place-items: center;
  width: 2.75rem;
  height: 2.75rem;
  border-radius: 50%;
  background: var(--ehs-primary-soft);
  color: var(--ehs-primary);
  object-fit: cover;
  font-weight: 700;
  flex-shrink: 0;
}

.ehs-progress {
  display: block;
  width: 100%;
  height: .65rem;
  border: 0;
  border-radius: 1rem;
  overflow: hidden;
  background: var(--ehs-border);
  accent-color: var(--ehs-primary);
}

.ehs-progress::-webkit-progress-bar {
  background: var(--ehs-border);
}

.ehs-progress::-webkit-progress-value {
  background: var(--ehs-primary);
}

.ehs-progress::-moz-progress-bar {
  background: var(--ehs-primary);
}

.ehs-spinner {
  display: inline-block;
  width: 1.5rem;
  height: 1.5rem;
  border: 3px solid var(--ehs-border);
  border-block-start-color: var(--ehs-primary);
  border-radius: 50%;
