html[lang^="ar"] .ehs-ui, .ehs-ui:lang(ar), .ehs-ui :lang(ar) {
  font-family: var(--ehs-font-arabic);
  letter-spacing: normal;
}

.ehs-ui:dir(rtl) {
  text-align: start;
}

.ehs-ui:dir(rtl) .ehs-field > .ehs-label {
  transform-origin: right center;
}

.ehs-ui:dir(rtl) dialog.ehs-drawer {
  --ehs-drawer-enter: 2rem;
}

.ehs-ui .ehs-icon-directional:dir(rtl) {
  transform: scaleX(-1);
}

.ehs-number,.ehs-code,.ehs-phone {
  direction: ltr;
  unicode-bidi: isolate;
  font-variant-numeric: tabular-nums;
}

.ehs-ui:dir(rtl) .ehs-yii .pagination {
  padding-inline-start: 0;
}

.ehs-ui:dir(rtl) .ehs-datatable :is(.dt-search,.dt-length,.dataTables_filter,.dataTables_length) {
  text-align: start;
}

.ehs-ui:dir(rtl) .ehs-select2 .select2-container .select2-selection__rendered {
  text-align: start;
}

.ehs-ui:dir(rtl) .ehs-select2 .select2-selection--single .select2-selection__arrow {
  right: auto;
  left: .5rem;
}

.ehs-ui:dir(rtl) .ehs-select2 .select2-selection--multiple .select2-selection__choice {
  float: none;
  margin-inline: 0 .25rem;
}

.ehs-ui:dir(rtl) .ehs-datepicker .input-group-addon {
  border-radius: 4px 0 0 4px;
}

@media (max-width: 767.98px) {
  .ehs-ui:lang(ar) {
    line-height: 1.7;
  }
}

.ehs-ui .ehs-yii .form-group {
  margin-block-end: 1.25rem;
}

.ehs-ui .ehs-yii :is(.help-block,.hint-block) {
  margin-block: .25rem 0;
  font-size: .75rem;
  line-height: 1rem;
}

.ehs-ui .ehs-yii .help-block {
  color: var(--ehs-danger);
}

.ehs-ui .ehs-yii .hint-block {
  color: var(--ehs-muted);
}

.ehs-ui .ehs-yii .has-error :is(.ehs-input,.ehs-select,.ehs-textarea,.form-control) {
  border-color: var(--ehs-danger);
  box-shadow: inset 0 0 0 1px var(--ehs-danger);
}

.ehs-ui .ehs-yii .has-error :is(.ehs-label,.control-label) {
  color: var(--ehs-danger);
}

.ehs-ui .ehs-yii .has-error .ehs-field-filled :is(.ehs-input,.ehs-select,.ehs-textarea) {
  box-shadow: none;
  border-block-end-color: var(--ehs-danger);
}

.ehs-ui .ehs-yii .has-success :is(.ehs-input,.ehs-select,.ehs-textarea) {
  border-color: var(--ehs-success);
}

.ehs-ui .ehs-yii .error-summary {
  padding: 1rem;
  margin-block-end: 1rem;
  border-radius: 12px;
  background: var(--ehs-danger-soft);
  color: var(--ehs-on-danger-soft);
}

.ehs-ui .ehs-yii .error-summary ul {
  margin-block: .5rem 0;
}

.ehs-ui .ehs-yii .summary {
  color: var(--ehs-muted);
  font-size: .875rem;
  padding-block: .75rem;
}

.ehs-ui .ehs-yii .filters :is(input,select),.ehs-ui .ehs-yii .form-control {
  min-height: 2.75rem;
  width: 100%;
  min-width: 0;
  padding: .5rem .75rem;
  border: 1px solid var(--ehs-control-border);
  border-radius: 4px;
  background: var(--md-sys-input-background);
  color: var(--ehs-text);
  font: inherit;
}

.ehs-ui .ehs-yii .filters :is(input,select):focus {
  outline: 2px solid var(--ehs-primary);
  outline-offset: -2px;
}

.ehs-ui .ehs-yii .filters select option {
  background: var(--ehs-surface);
}

.ehs-ui .ehs-yii .grid-view {
  min-width: 0;
}

.ehs-ui .ehs-yii .pagination {
  display: flex;
  flex-wrap: wrap;
  gap: .25rem;
  list-style: none;
  padding: 0;
  margin-block: 1rem;
}

.ehs-ui .ehs-yii .pagination > li > :is(a,span) {
  display: inline-grid;
  place-items: center;
  min-width: 2.75rem;
  min-height: 2.75rem;
  padding: .5rem;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--ehs-primary);
  text-decoration: none;
}

.ehs-ui .ehs-yii .pagination > .active > :is(a,span) {
  background: var(--ehs-secondary-soft);
  color: var(--ehs-on-secondary-soft);
  font-weight: 600;
}

.ehs-ui .ehs-yii .pagination > .disabled > :is(a,span) {
  color: var(--ehs-muted);
  opacity: .45;
}

.ehs-ui .ehs-yii th > a {
  display: inline-block;
  padding-block: .35rem;
  color: var(--ehs-muted);
  text-decoration: none;
}

.ehs-ui .ehs-yii th > a.asc::after {
  content: " ↑";
}

.ehs-ui .ehs-yii th > a.desc::after {
  content: " ↓";
}

.ehs-ui .ehs-yii .detail-view {
  width: 100%;
  border-collapse: collapse;
  background: var(--ehs-surface);
}

.ehs-ui .ehs-yii .detail-view :is(th,td) {
  padding: .875rem 1rem;
  border-block-end: 1px solid var(--ehs-border);
  text-align: start;
}

.ehs-ui .ehs-yii .list-view .item {
  margin-block-end: 1rem;
}

.ehs-ui .ehs-yii [aria-busy="true"],.ehs-ui .ehs-datatable [aria-busy="true"] {
  cursor: progress;
}

.ehs-ui .ehs-datatable {
  min-width: 0;
}

.ehs-ui .ehs-datatable :is(.dt-container,.dataTables_wrapper) {
  color: var(--ehs-text);
  font: inherit;
}

.ehs-ui .ehs-datatable :is(.dt-layout-row,.ehs-dt-toolbar) {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: .75rem;
  margin-block: .75rem;
}

.ehs-ui .ehs-datatable :is(.dt-layout-cell,.dt-layout-table,.dt-layout-full) {
  min-width: 0;
  max-width: 100%;
}

.ehs-ui .ehs-datatable :is(.dt-layout-table,.dt-layout-full) {
  width: 100%;
}

.ehs-ui .ehs-datatable :is(.dt-input,.dataTables_filter input,.dataTables_length select) {
  min-height: 2.5rem;
  padding: .5rem .75rem;
  margin-inline: .5rem 0;
  border: 1px solid var(--ehs-control-border);
  border-radius: 4px;
  background: var(--md-sys-input-background);
  color: var(--ehs-text);
  font: inherit;
  max-width: 100%;
}

.ehs-ui .ehs-datatable select option {
  background: var(--ehs-surface);
}

.ehs-ui .ehs-datatable :is(.dt-info,.dataTables_info) {
  color: var(--ehs-muted);
  font-size: .875rem;
}

.ehs-ui .ehs-datatable :is(.dt-paging-button,.dataTables_paginate .paginate_button) {
  min-width: 2.5rem;
  min-height: 2.5rem;
  padding: .5rem;
  margin-inline: .125rem;
  border: 0 !important;
  border-radius: 999px;
  color: var(--ehs-primary) !important;
  background: transparent !important;
  box-shadow: none !important;
  cursor: pointer;
}

.ehs-ui .ehs-datatable :is(.dt-paging-button.current,.dataTables_paginate .paginate_button.current) {
  background: var(--ehs-secondary-soft) !important;
  color: var(--ehs-on-secondary-soft) !important;
}

.ehs-ui .ehs-datatable :is(.dt-paging-button.disabled,.dataTables_paginate .paginate_button.disabled) {
  opacity: .45;
  cursor: default;
}

.ehs-ui .ehs-datatable table.dataTable {
  width: 100%;
  border-collapse: collapse !important;
  color: var(--ehs-text);
}

.ehs-ui .ehs-datatable table.dataTable :is(th,td) {
  padding: .875rem 1rem;
  border-block-end: 1px solid var(--ehs-border);
  box-shadow: none;
}

.ehs-ui .ehs-datatable table.dataTable thead th {
  background: var(--md-sys-color-surface-container);
  color: var(--ehs-muted);
  padding-inline-end: 2rem;
}

.ehs-ui .ehs-datatable table.dataTable tbody tr {
  background: var(--ehs-surface);
}

.ehs-ui .ehs-datatable table.dataTable tbody tr:nth-child(even) {
  background: var(--cmp-table-even-row);
}

.ehs-ui .ehs-datatable table.dataTable tbody tr:hover {
  background: var(--cmp-table-hover);
}

.ehs-ui .ehs-datatable table.dataTable tbody tr.selected {
  background: var(--ehs-secondary-soft);
  color: var(--ehs-on-secondary-soft);
}

.ehs-ui .ehs-datatable .dt-button {
  padding: .625rem 1.25rem;
  margin-inline-end: .5rem;
  border: 1px solid var(--ehs-control-border);
  border-radius: 999px;
  background: transparent;
  color: var(--ehs-primary);
  font: inherit;
}

.ehs-ui .ehs-datatable :is(.dt-processing,.dataTables_processing) {
  background: var(--md-sys-color-surface-container-high);
  color: var(--ehs-text);
  border-radius: 12px;
  box-shadow: var(--ehs-shadow-2);
}

.ehs-ui .ehs-select2 {
  min-width: 0;
  position: relative;
}

.ehs-ui .ehs-select2 .select2-container {
  max-width: 100%;
  width: 100% !important;
  font: inherit;
}

.ehs-ui .ehs-select2 :is(.select2-selection--single,.select2-selection--multiple) {
  min-height: var(--ehs-control-height);
  border: 1px solid var(--ehs-control-border);
  border-radius: 4px;
  background: var(--md-sys-input-background);
  color: var(--ehs-text);
}

.ehs-ui .ehs-select2 .select2-selection--single {
  display: flex;
  align-items: center;
  height: auto;
}

.ehs-ui .ehs-select2 .select2-selection--single .select2-selection__rendered {
  padding-inline: .75rem 2rem;
  color: var(--ehs-text);
}

.ehs-ui .ehs-select2 .select2-selection--single .select2-selection__arrow {
  top: 50%;
  transform: translateY(-50%);
}

.ehs-ui .ehs-select2 .select2-selection--multiple .select2-selection__rendered {
  display: flex;
  flex-wrap: wrap;
  gap: .25rem;
  padding: .375rem;
  white-space: normal;
}

.ehs-ui .ehs-select2 .select2-selection__choice {
  display: inline-flex;
  align-items: center;
  white-space: normal;
  overflow-wrap: anywhere;
  background: var(--ehs-secondary-soft);
  color: var(--ehs-on-secondary-soft);
  border: 0;
  border-radius: 8px;
  min-height: 2rem;
  margin: .125rem;
  padding: .25rem .5rem;
}

.ehs-ui .ehs-select2 .select2-selection__choice__remove {
  position: static;
  margin-inline-end: .4rem;
  color: inherit;
  border: 0;
  background: transparent;
}

.ehs-ui .ehs-select2 .select2-search__field {
  font: inherit;
  color: var(--ehs-text);
  max-width: 100%;
}

.ehs-ui .ehs-select2 .select2-dropdown {
  background: var(--md-sys-color-surface-container);
  border: 1px solid var(--ehs-border);
  border-radius: 4px;
  box-shadow: var(--ehs-shadow-2);
  color: var(--ehs-text);
}

.ehs-ui .ehs-select2 .select2-results__option {
  padding: .75rem;
}

.ehs-ui .ehs-select2 :is(.select2-results__option--highlighted,.select2-results__option--selected,[aria-selected="true"]) {
  background: var(--ehs-secondary-soft);
  color: var(--ehs-on-secondary-soft);
}

.ehs-ui .ehs-select2 .select2-container--focus .select2-selection {
  border-color: var(--ehs-primary);
  outline: 1px solid var(--ehs-primary);
}

.ehs-ui .ehs-yii .has-error .select2-selection {
  border-color: var(--ehs-danger);
}

.ehs-ui .ehs-select2 .select2-container--disabled .select2-selection {
  opacity: .5;
}

.ehs-ui .ehs-datepicker .input-group {
  display: flex;
}

.ehs-ui .ehs-datepicker .input-group .form-control {
  min-width: 0;
  flex: 1;
}

.ehs-ui .ehs-datepicker .input-group-addon {
  display: inline-flex;
  align-items: center;
  padding-inline: .75rem;
  border: 1px solid var(--ehs-control-border);
  background: var(--ehs-primary-soft);
  color: var(--ehs-on-primary-soft);
}

@media (max-width: 767.98px) {
  .ehs-ui .ehs-datatable :is(.dt-layout-row,.ehs-dt-toolbar) {
    flex-direction: column;
    align-items: stretch;
  }
}

@media (max-width: 767.98px) {
  .ehs-ui .ehs-datatable :is(.dt-search,.dt-length,.dataTables_filter,.dataTables_length,.dataTables_info,.dataTables_paginate) {
    float: none !important;
    text-align: start !important;
    width: 100%;
    margin-block: .5rem;
  }
}

@media (max-width: 767.98px) {
  .ehs-ui .ehs-datatable :is(.dt-paging,.dataTables_paginate) {
    display: flex;
    flex-wrap: wrap;
  }
}

stylesheets.css:
/* User-supplied light tokens. Values preserved. */
:root {
  /* ********** Typography ********** */
  --md-sys-font-family-base: "Roboto", "Almarai", "Helvetica", "Arial", sans-serif;

  /* ********** Brand Colors ********** */
  --md-sys-color-primary: #00538e;
  --md-sys-color-secondary: #535f70;
  --md-sys-color-tertiary: #00a9d7;
  --md-sys-color-mix: #007bad;
  --md-sys-color-error: #ba1a1a;
  --md-sys-color-inverse-primary: #a1cafd;

  /* ********** Container Colors ********** */
  --md-sys-color-primary-container: #d2e4ff;
  --md-sys-color-tertiary-container: #bde9ff;
  --md-sys-color-error-container: #ffdad6;

  /* ********** On Colors ********** */
  --md-sys-color-on-primary: #ffffff;
  --md-sys-color-on-secondary: #ffffff;
  --md-sys-color-on-primary-container: #001d36;
  --md-sys-color-on-error-container: rgb(65 0 2);
  --md-sys-color-on-surface-variant: rgb(67 71 78);
  --md-sys-color-on-surface: rgb(25 28 32);

  /* ********** Surface & Background Colors ********** */
  --md-sys-color-background: #f8f9ff;
  --md-sys-color-surface: #f8f9ff;
  --md-sys-color-surface-muted: #f8f9fa;
  --md-sys-color-surface-subtle: #f9fafb;
  --md-sys-color-surface-accent: #e6f2ff;
  --md-sys-color-surface-accent-soft: #f0f7fd;
  --md-sys-color-surface-accent-soft-alpha-30: rgba(240, 247, 253, 0.3);
  --md-sys-color-surface-glass: rgba(255, 255, 255, 0.15);
  --md-sys-color-surface-container: #eceef4;
  --md-sys-color-surface-container-low: #f2f3fa;
  --md-sys-color-surface-container-lowest: #ffffff;
  --md-sys-input-background: rgb(0 169 215 / 6%);

  /* ********** Border Colors ********** */
  --md-sys-color-outline: #73777f;
  --md-sys-color-outline-variant: #c3c6cf;
  --md-sys-color-border-primary-soft: rgba(0, 29, 54, 0.2);
  --md-sys-color-border-divider: rgba(0, 0, 0, 0.2);
  --md-sys-color-border-light: #e6e6e6;
  --md-sys-color-border-soft: #e2e8f0;
  --md-sys-color-border-muted: #d0d5dd;

  /* ********** Text Colors ********** */
  --md-sys-color-text-primary: #212529;
  --md-sys-color-text-secondary: #343a40;
  --md-sys-color-text-dark: #1e293b;
  --md-sys-color-text-muted: #64748b;
  --md-sys-color-text-hint: #475569;
  --md-sys-color-heading-primary: #004c7d;

  /* ********** Neutral Colors ********** */
  --md-sys-color-neutral-dark: #231f20;
  --md-sys-color-neutral-medium: #3f5351;

  /* ********** Primary Variants ********** */
  --md-sys-color-primary-soft: rgba(7, 92, 153, 0.03);
  --md-sys-color-primary-outline-soft: rgba(7, 92, 153, 0.08);
  --md-sys-color-primary-gradient-end: #0a4a7a;
  --md-sys-color-primary-gradient-hover-start: #0a5ba8;
  --md-sys-color-primary-gradient-hover-end: #0d4463;

  /* ********** Danger Variants ********** */
  --md-sys-color-danger-soft: rgba(239, 68, 68, 0.1);
  --md-sys-color-danger-hover: #dc2626;

  /* ********** Info Colors ********** */
  --md-sys-color-info-border: #0b6cbf;
  --md-sys-color-info-hover: rgba(7, 92, 153, 0.08);

  /* ********** File Card Colors ********** */
  --md-sys-color-file-gradient-start: #ffffff;
  --md-sys-color-file-gradient-end: #fefefe;

  /* ********** Shadow & Overlay Colors ********** */
  --md-sys-color-overlay: rgb(0 0 0 / 50%);
  --md-sys-color-overlay-white-animation: rgba(255, 255, 255, 0) 0%,
    rgba(255, 255, 255, 0.3);
  --md-sys-color-shadow-soft: rgba(0, 0, 0, 0.06);
  --md-sys-color-shadow-container: rgba(17, 17, 26, 0.03);
  --md-sys-color-primary-shadow-strong: rgba(7, 92, 153, 0.35);
  --md-sys-color-primary-shadow-medium: rgba(7, 92, 153, 0.25);
  --md-sys-color-scrim-strong: rgba(0, 0, 0, 0.5);

  /* ********** Elevation ********** */
  --md-sys-elevation-1: rgba(0, 0, 0, 0.1);
  --md-sys-elevation-2: rgba(149, 157, 165, 0.2) 0px 8px 24px;
  --md-sys-elevation-header:
    0 2px 2px rgb(0 0 0 / 14%),
    0 3px 1px -2px rgb(0 0 0 / 20%),
    0 1px 5px rgb(0 0 0 / 12%);

  /* ********** Fixed Colors ********** */
  --md-sys-color-white-insist: #fff;
  --md-sys-color-black-insist: #000;

  /* ********** Buttons & Interactions ********** */
  --cmp-shadow: #999;
  --cmp-disabled-bg: #eee;
  --cmp-ripple-active: rgb(0 0 0 / 28%);

  /* ********** Modals ********** */
  --cmp-modal-hover-bg: rgba(205, 224, 219, 0.4);
  --cmp-modal-shadow-1: rgba(0, 0, 0, 0.14);
  --cmp-modal-shadow-2: rgba(0, 0, 0, 0.12);

  /* ********** Forms & Inputs ********** */
  --cmp-border-default: rgba(0, 0, 0, 0.42);
  --cmp-placeholder: rgba(255, 255, 255, 0.582);
  --cmp-autofill-bg: #e8f0fe;
  --cmp-readonly-bg: #f0f4f8;

  /* ********** Radio & Checkbox ********** */
  --cmp-radio-border: #c8ccd4;
  --cmp-radio-hover-opacity: 0.08;
  --cmp-checkbox-disabled-opacity: 0.5;

  /* ********** Accordion ********** */
  --cmp-accordion-bg: #f6fbff;

  /* ********** Tabs ********** */
  --cmp-tab-bg: rgb(47 119 139 / 34%);
  --cmp-tab-hover: rgba(255, 255, 255, 0.2);
  --cmp-tab-active-text: #001d36;

  /* ********** Spinner ********** */
  --cmp-spinner-overlay: rgb(0 0 0 / 65%);

  /* ********** Search ********** */
  --cmp-sys-card-surface: #edf4fd;
  --cmp-search-border: rgba(0, 0, 0, 0.12);
  --cmp-search-text: rgba(0, 0, 0, 0.87);

  /* ********** Select & Dropdown ********** */
  --cmp-select-arrow: #343a40;
  --cmp-select2-bg: rgb(0 169 215 / 6%);
  --cmp-dropdown-shadow-1: rgba(0, 0, 0, 0.08);
  --cmp-dropdown-shadow-2: rgba(0, 0, 0, 0.04);

  /* ********** Alerts ********** */
  --cmp-alert-primary-text: #001d36;
  --cmp-alert-primary-bg: #d2e4ff;
  --cmp-alert-info-bg: #3f5351;
  --cmp-alert-warning-text: #231f20;
  --cmp-alert-warning-bg: #e8cd8e;
  --cmp-alert-danger-bg: #b84242;
  --cmp-alert-success-bg: #1c8a66;
  --cmp-alert-light-bg: #f4f4f2;
  --cmp-alert-dark-bg: #231f20;

  /* ********** Pagination ********** */
  --cmp-pagination-border: #ddd;
  --cmp-pagination-icon: #808080;
  --cmp-pagination-active: #035c9c;

  /* ********** Tables ********** */
  --cmp-table-even-row: #f7f8fa;
  --cmp-table-hover: #c2e7ff;
  --cmp-table-border: #edf2f7;
  --cmp-table-sort-hover: #9ee7ff;

  /* ********** Tooltips ********** */
  --cmp-tooltip-bg: #303030;
  --cmp-tooltip-text: #fff;

  /* ********** Footer ********** */
  --cmp-footer-bg: #e1e1e1;
  --cmp-footer-shadow-1: rgba(0, 0, 0, 0.15);
  --cmp-footer-shadow-2: rgba(0, 0, 0, 0.25);

  /* ********** Error Pages ********** */
  --cmp-error-text: rgba(255, 255, 255, 0.7);
  --cmp-error-bg: #a3abbd;
  --cmp-error-page-bg: #f0f4f8;
  --cmp-error-page-number-gradient-start: var(--md-sys-color-primary);
  --cmp-error-page-number-gradient-end: var(--md-sys-color-tertiary);
  --cmp-error-page-box-shadow: 0 4px 16px rgba(0, 83, 142, 0.08);

  /* ********** Page Title ********** */
  --cmp-page-title-bg: rgba(63, 71, 86, 1);
  --cmp-page-title-bg-variant: rgba(0, 83, 142, 0.06);
  --cmp-page-title-border: rgba(0, 83, 142, 0.14);
  --cmp-page-title-shadow: rgba(0, 102, 161, 0.15);
  --cmp-page-title-icon-text: rgba(255, 255, 255, 0.95);
  --cmp-page-title-icon-bg: rgba(255, 255, 255, 0.2);

  /* ********** Scrollbar ********** */
  --cmp-scrollbar-track: #f1f1f1;
  --cmp-scrollbar-thumb: #a8a8a8;
  --cmp-scrollbar-thumb-hover: rgba(0, 0, 0, 0.5);
  --cmp-scrollbar-size: 10px;

  /* ********** View/Update Request ********** */
  --page-vu-request-section-bg: #fcfdff;
  --page-vu-request-section-border: rgba(0, 83, 142, 0.08);
  --page-vu-header-divider: rgba(0, 83, 142, 0.1);
  --page-pv-field-info-group-border: rgba(0, 83, 142, 0.12);

  /* ********** Deep Dark Colors ********** */
  --md-sys-color-deep-black: #191c20;
  --md-sys-color-charcoal: #1c2130;
  --md-sys-color-midnight: #0f1629;
  --md-sys-color-dark-gray: #333333;
  --md-sys-color-graphite: #404040;

  /* ********** Primary Blue Variants ********** */
  --md-sys-color-primary-dark: #003c78;
  --md-sys-color-primary-deep: #004272;
  --md-sys-color-primary-hover: #004c89;
  --md-sys-color-primary-bright: #006dcc;
  --md-sys-color-primary-light: #1976d2;
  --md-sys-color-primary-soft-light: #dae7fd;
  --md-sys-color-primary-soft-bg: #cfe2ff;
  --md-sys-color-primary-hover-bg: #c2e7fe;
  --md-sys-color-primary-softest-bg: #eef6fa;

  /* ********** Cyan & Accent Variants ********** */
  --md-sys-color-accent-bright: #059cd8;
  --md-sys-color-accent-primary: #00aad8;
  --md-sys-color-accent-light: #71bff7;

  /* ********** Red & Danger Variants ********** */
  --md-sys-color-danger-text: #a94442;
  --md-sys-color-danger-border: #eed3d7;
  --md-sys-color-danger-soft-bg: #fdf7f7;
  --md-sys-color-danger-light-bg: #ffe6e6;
  --md-sys-color-danger-bright: #f44336;
  --md-sys-color-danger-strong: #b91c1c;
  --md-sys-color-danger-accent: #fa3e3e;

  /* ********** Yellow & Warning Variants ********** */
  --md-sys-color-warning-soft: #fde19a;
  --md-sys-color-warning-light: #fdf59a;
  --md-sys-color-warning-bright: #fbf069;

  /* ********** Light Surface Colors ********** */
  --md-sys-color-surface-soft: #f0f4f9;
  --md-sys-color-surface-softest: #f8fafd;
  --md-sys-color-surface-light: #f8f9fc;
  --md-sys-color-surface-muted-light: #f2f4f7;
  --md-sys-color-surface-card: #f7f9fc;
  --md-sys-color-surface-hover: #f1f5f9;
  --md-sys-color-surface-accent-light: #f0f9ff;
  --md-sys-color-surface-accent-muted: #e0f2fe;
  --md-sys-color-surface-gray: #f5f5f5;

  /* ********** Neutral Border Colors ********** */
  --md-sys-color-border-gray-light: #e5e5e5;
  --md-sys-color-border-gray-soft: #e8e8e8;
  --md-sys-color-border-gray-muted: #e0e0e0;
  --md-sys-color-border-neutral: #d3d3d3;
  --md-sys-color-border-subtle: #e5e7eb;
  --md-sys-color-border-medium: #d1d5db;
  --md-sys-color-border-dark-soft: #c1c8d0;
  --md-sys-color-border-dark-muted: #cdd0da;

  /* ********** Slate Text Variants ********** */
  --md-sys-color-text-slate: #334155;
  --md-sys-color-text-slate-light: #6b7280;
  --md-sys-color-text-gray: #6c757d;
  --md-sys-color-text-muted-dark: #757575;
  --md-sys-color-text-muted-soft: #7a8299;
  --md-sys-color-text-muted-medium: #9aa0b0;
  --md-sys-color-text-neutral: #6f6e6e;
  --md-sys-color-text-light-gray: #777777;
  --md-sys-color-text-light-gray-2: #888888;
  --md-sys-color-text-dark-slate: #374151;

  /* ********** Cool Gray Surfaces ********** */
  --md-sys-color-cool-gray-100: #e3e9ee;
  --md-sys-color-cool-gray-200: #eaecf0;
  --md-sys-color-cool-gray-300: #e8eaf0;
  --md-sys-color-cool-gray-400: #eceef3;
  --md-sys-color-cool-gray-500: #e4e6ed;
  --md-sys-color-cool-gray-600: #eceaea;
  --md-sys-color-cool-gray-700: #e3edf7;
  --md-sys-color-cool-gray-800: #e6eef4;

  /* ********** Indigo Variants ********** */
  --md-sys-color-indigo: #3f51b5;
  --md-sys-color-indigo-dark: #1a3a5c;

  /* ********** Transparent White Variants ********** */
  --md-sys-color-white-0: rgba(255, 255, 255, 0);
  --md-sys-color-white-12: rgba(255, 255, 255, 0.12);
  --md-sys-color-white-25: rgba(255, 255, 255, 0.25);
  --md-sys-color-white-30: rgba(255, 255, 255, 0.3);
  --md-sys-color-white-38: rgba(255, 255, 255, 0.38);
  --md-sys-color-white-75: rgba(255, 255, 255, 0.75);
  --md-sys-color-white-80: rgba(255, 255, 255, 0.8);
  --md-sys-color-white-100: rgba(255, 255, 255, 1);

  /* ********** Transparent Black Variants ********** */
  --md-sys-color-black-2: rgba(0, 0, 0, 0.02);
  --md-sys-color-black-5: rgba(0, 0, 0, 0.05);
  --md-sys-color-black-30: rgba(0, 0, 0, 0.3);
  --md-sys-color-black-35: rgba(0, 0, 0, 0.35);
  --md-sys-color-black-37: rgba(0, 0, 0, 0.37);
  --md-sys-color-black-40: rgba(0, 0, 0, 0.4);
  --md-sys-color-black-54: rgba(0, 0, 0, 0.54);
  --md-sys-color-black-55: rgba(0, 0, 0, 0.55);
  --md-sys-color-black-60: rgba(0, 0, 0, 0.6);
  --md-sys-color-black-70: rgba(0, 0, 0, 0.7);
  --md-sys-color-black-75: rgba(0, 0, 0, 0.75);
  --md-sys-color-black-76: rgba(0, 0, 0, 0.76);
  --md-sys-color-black-80: rgba(0, 0, 0, 0.8);

  /* ********** Transparent Brand Variants ********** */
