/* Load AFTER ehs.css and widget adapters on Arabic pages. Set <html lang="ar" dir="rtl">. */
html[lang^="ar"] .ehs-ui, .ehs-ui:lang(ar), .ehs-ui :lang(ar) {
  font-family: var(--ehs-font-arabic); letter-spacing: normal;
}
.ehs-ui:dir(rtl) { text-align: start; }
.ehs-ui:dir(rtl) .ehs-field > .ehs-label { transform-origin: right center; }
.ehs-ui:dir(rtl) dialog.ehs-drawer { --ehs-drawer-enter: 2rem; }
.ehs-ui .ehs-icon-directional:dir(rtl) { transform: scaleX(-1); }
.ehs-number,.ehs-code,.ehs-phone { direction: ltr; unicode-bidi: isolate; font-variant-numeric: tabular-nums; }
.ehs-ui:dir(rtl) .ehs-yii .pagination { padding-inline-start: 0; }
.ehs-ui:dir(rtl) .ehs-datatable :is(.dt-search,.dt-length,.dataTables_filter,.dataTables_length) { text-align: start; }
.ehs-ui:dir(rtl) .ehs-select2 .select2-container .select2-selection__rendered { text-align: start; }
.ehs-ui:dir(rtl) .ehs-select2 .select2-selection--single .select2-selection__arrow { right: auto; left: .5rem; }
.ehs-ui:dir(rtl) .ehs-select2 .select2-selection--multiple .select2-selection__choice { float: none; margin-inline: 0 .25rem; }
.ehs-ui:dir(rtl) .ehs-datepicker .input-group-addon { border-radius: 4px 0 0 4px; }
@media (max-width: 767.98px) { .ehs-ui:lang(ar) { line-height: 1.7; } }

/* Opt-in adapters. Load after Yii/Kartik/Select2/DataTables vendor styles and after ehs.css. */
.ehs-ui .ehs-yii .form-group { margin-block-end: 1.25rem; }
.ehs-ui .ehs-yii :is(.help-block,.hint-block) { margin-block: .25rem 0; font-size: .75rem; line-height: 1rem; }
.ehs-ui .ehs-yii .help-block { color: var(--ehs-danger); }
.ehs-ui .ehs-yii .hint-block { color: var(--ehs-muted); }
.ehs-ui .ehs-yii .has-error :is(.ehs-input,.ehs-select,.ehs-textarea,.form-control) { border-color: var(--ehs-danger); box-shadow: inset 0 0 0 1px var(--ehs-danger); }
.ehs-ui .ehs-yii .has-error :is(.ehs-label,.control-label) { color: var(--ehs-danger); }
.ehs-ui .ehs-yii .has-error .ehs-field-filled :is(.ehs-input,.ehs-select,.ehs-textarea) { box-shadow: none; border-block-end-color: var(--ehs-danger); }
.ehs-ui .ehs-yii .has-success :is(.ehs-input,.ehs-select,.ehs-textarea) { border-color: var(--ehs-success); }
.ehs-ui .ehs-yii .error-summary { padding: 1rem; margin-block-end: 1rem; border-radius: 12px; background: var(--ehs-danger-soft); color: var(--ehs-on-danger-soft); }
.ehs-ui .ehs-yii .error-summary ul { margin-block: .5rem 0; }
.ehs-ui .ehs-yii .summary { color: var(--ehs-muted); font-size: .875rem; padding-block: .75rem; }
.ehs-ui .ehs-yii .filters :is(input,select),.ehs-ui .ehs-yii .form-control { min-height: 2.75rem; width: 100%; min-width: 0; padding: .5rem .75rem; border: 1px solid var(--ehs-control-border); border-radius: 4px; background: var(--md-sys-input-background); color: var(--ehs-text); font: inherit; }
.ehs-ui .ehs-yii .filters :is(input,select):focus { outline: 2px solid var(--ehs-primary); outline-offset: -2px; }
.ehs-ui .ehs-yii .filters select option { background: var(--ehs-surface); }
.ehs-ui .ehs-yii .grid-view { min-width: 0; }
.ehs-ui .ehs-yii .pagination { display: flex; flex-wrap: wrap; gap: .25rem; list-style: none; padding: 0; margin-block: 1rem; }
.ehs-ui .ehs-yii .pagination > li > :is(a,span) { display: inline-grid; place-items: center; min-width: 2.75rem; min-height: 2.75rem; padding: .5rem; border: 0; border-radius: 999px; background: transparent; color: var(--ehs-primary); text-decoration: none; }
.ehs-ui .ehs-yii .pagination > .active > :is(a,span) { background: var(--ehs-secondary-soft); color: var(--ehs-on-secondary-soft); font-weight: 600; }
.ehs-ui .ehs-yii .pagination > .disabled > :is(a,span) { color: var(--ehs-muted); opacity: .45; }
.ehs-ui .ehs-yii th > a { display: inline-block; padding-block: .35rem; color: var(--ehs-muted); text-decoration: none; }
.ehs-ui .ehs-yii th > a.asc::after { content: " ↑"; }
.ehs-ui .ehs-yii th > a.desc::after { content: " ↓"; }
.ehs-ui .ehs-yii .detail-view { width: 100%; border-collapse: collapse; background: var(--ehs-surface); }
.ehs-ui .ehs-yii .detail-view :is(th,td) { padding: .875rem 1rem; border-block-end: 1px solid var(--ehs-border); text-align: start; }
.ehs-ui .ehs-yii .list-view .item { margin-block-end: 1rem; }
.ehs-ui .ehs-yii [aria-busy="true"],.ehs-ui .ehs-datatable [aria-busy="true"] { cursor: progress; }
/* DataTables 1.13 and 2.x CSS hooks: behavior remains vendor-owned. */
.ehs-ui .ehs-datatable { min-width: 0; }
.ehs-ui .ehs-datatable :is(.dt-container,.dataTables_wrapper) { color: var(--ehs-text); font: inherit; }
.ehs-ui .ehs-datatable :is(.dt-layout-row,.ehs-dt-toolbar) { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: .75rem; margin-block: .75rem; }
.ehs-ui .ehs-datatable :is(.dt-layout-cell,.dt-layout-table,.dt-layout-full) { min-width: 0; max-width: 100%; }
.ehs-ui .ehs-datatable :is(.dt-layout-table,.dt-layout-full) { width: 100%; }
.ehs-ui .ehs-datatable :is(.dt-input,.dataTables_filter input,.dataTables_length select) { min-height: 2.5rem; padding: .5rem .75rem; margin-inline: .5rem 0; border: 1px solid var(--ehs-control-border); border-radius: 4px; background: var(--md-sys-input-background); color: var(--ehs-text); font: inherit; max-width: 100%; }
.ehs-ui .ehs-datatable select option { background: var(--ehs-surface); }
.ehs-ui .ehs-datatable :is(.dt-info,.dataTables_info) { color: var(--ehs-muted); font-size: .875rem; }
.ehs-ui .ehs-datatable :is(.dt-paging-button,.dataTables_paginate .paginate_button) { min-width: 2.5rem; min-height: 2.5rem; padding: .5rem; margin-inline: .125rem; border: 0 !important; border-radius: 999px; color: var(--ehs-primary) !important; background: transparent !important; box-shadow: none !important; cursor: pointer; }
.ehs-ui .ehs-datatable :is(.dt-paging-button.current,.dataTables_paginate .paginate_button.current) { background: var(--ehs-secondary-soft) !important; color: var(--ehs-on-secondary-soft) !important; }
.ehs-ui .ehs-datatable :is(.dt-paging-button.disabled,.dataTables_paginate .paginate_button.disabled) { opacity: .45; cursor: default; }
.ehs-ui .ehs-datatable table.dataTable { width: 100%; border-collapse: collapse !important; color: var(--ehs-text); }
.ehs-ui .ehs-datatable table.dataTable :is(th,td) { padding: .875rem 1rem; border-block-end: 1px solid var(--ehs-border); box-shadow: none; }
.ehs-ui .ehs-datatable table.dataTable thead th { background: var(--md-sys-color-surface-container); color: var(--ehs-muted); padding-inline-end: 2rem; }
.ehs-ui .ehs-datatable table.dataTable tbody tr { background: var(--ehs-surface); }
.ehs-ui .ehs-datatable table.dataTable tbody tr:nth-child(even) { background: var(--cmp-table-even-row); }
.ehs-ui .ehs-datatable table.dataTable tbody tr:hover { background: var(--cmp-table-hover); }
.ehs-ui .ehs-datatable table.dataTable tbody tr.selected { background: var(--ehs-secondary-soft); color: var(--ehs-on-secondary-soft); }
.ehs-ui .ehs-datatable .dt-button { padding: .625rem 1.25rem; margin-inline-end: .5rem; border: 1px solid var(--ehs-control-border); border-radius: 999px; background: transparent; color: var(--ehs-primary); font: inherit; }
.ehs-ui .ehs-datatable :is(.dt-processing,.dataTables_processing) { background: var(--md-sys-color-surface-container-high); color: var(--ehs-text); border-radius: 12px; box-shadow: var(--ehs-shadow-2); }
/* Select2/Kartik: put the field AND its dropdownParent inside .ehs-select2. */
.ehs-ui .ehs-select2 { min-width: 0; position: relative; }
.ehs-ui .ehs-select2 .select2-container { max-width: 100%; width: 100% !important; font: inherit; }
.ehs-ui .ehs-select2 :is(.select2-selection--single,.select2-selection--multiple) { min-height: var(--ehs-control-height); border: 1px solid var(--ehs-control-border); border-radius: 4px; background: var(--md-sys-input-background); color: var(--ehs-text); }
.ehs-ui .ehs-select2 .select2-selection--single { display: flex; align-items: center; height: auto; }
.ehs-ui .ehs-select2 .select2-selection--single .select2-selection__rendered { padding-inline: .75rem 2rem; color: var(--ehs-text); }
.ehs-ui .ehs-select2 .select2-selection--single .select2-selection__arrow { top: 50%; transform: translateY(-50%); }
.ehs-ui .ehs-select2 .select2-selection--multiple .select2-selection__rendered { display: flex; flex-wrap: wrap; gap: .25rem; padding: .375rem; white-space: normal; }
.ehs-ui .ehs-select2 .select2-selection__choice { display: inline-flex; align-items: center; white-space: normal; overflow-wrap: anywhere; background: var(--ehs-secondary-soft); color: var(--ehs-on-secondary-soft); border: 0; border-radius: 8px; min-height: 2rem; margin: .125rem; padding: .25rem .5rem; }
.ehs-ui .ehs-select2 .select2-selection__choice__remove { position: static; margin-inline-end: .4rem; color: inherit; border: 0; background: transparent; }
.ehs-ui .ehs-select2 .select2-search__field { font: inherit; color: var(--ehs-text); max-width: 100%; }
.ehs-ui .ehs-select2 .select2-dropdown { background: var(--md-sys-color-surface-container); border: 1px solid var(--ehs-border); border-radius: 4px; box-shadow: var(--ehs-shadow-2); color: var(--ehs-text); }
.ehs-ui .ehs-select2 .select2-results__option { padding: .75rem; }
.ehs-ui .ehs-select2 :is(.select2-results__option--highlighted,.select2-results__option--selected,[aria-selected="true"]) { background: var(--ehs-secondary-soft); color: var(--ehs-on-secondary-soft); }
.ehs-ui .ehs-select2 .select2-container--focus .select2-selection { border-color: var(--ehs-primary); outline: 1px solid var(--ehs-primary); }
.ehs-ui .ehs-yii .has-error .select2-selection { border-color: var(--ehs-danger); }
.ehs-ui .ehs-select2 .select2-container--disabled .select2-selection { opacity: .5; }
/* Date inputs/addons; a picker library still owns calendar behavior and its popup styling. */
.ehs-ui .ehs-datepicker .input-group { display: flex; }
.ehs-ui .ehs-datepicker .input-group .form-control { min-width: 0; flex: 1; }
.ehs-ui .ehs-datepicker .input-group-addon { display: inline-flex; align-items: center; padding-inline: .75rem; border: 1px solid var(--ehs-control-border); background: var(--ehs-primary-soft); color: var(--ehs-on-primary-soft); }
@media (max-width: 767.98px) {
  .ehs-ui .ehs-datatable :is(.dt-layout-row,.ehs-dt-toolbar) { flex-direction: column; align-items: stretch; }
  .ehs-ui .ehs-datatable :is(.dt-search,.dt-length,.dataTables_filter,.dataTables_length,.dataTables_info,.dataTables_paginate) { float: none !important; text-align: start !important; width: 100%; margin-block: .5rem; }
  .ehs-ui .ehs-datatable :is(.dt-paging,.dataTables_paginate) { display: flex; flex-wrap: wrap; }
}
